const config = $input.first().json;

const parseJsonArray = (value, fieldName) => {
  if (typeof value !== 'string' || value.trim() === '') {
    return [];
  }

  try {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) {
      throw new Error(`${fieldName} must be a JSON array`);
    }

    return parsed
      .map((entry) => String(entry).trim())
      .filter(Boolean);
  } catch (error) {
    throw new Error(`Invalid ${fieldName}: ${error.message}`);
  }
};

const parsePositiveInteger = (value, fieldName, fallback) => {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }

  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${fieldName} must be a positive number`);
  }

  return Math.floor(parsed);
};

const vkBaseUrl = String(config.vkBaseUrl || '').trim().replace(/\/+$/, '');
const workflowId = String(config.workflowId || '').trim();
const githubToken = String(config.githubToken || '').trim();

if (!vkBaseUrl) {
  throw new Error('vkBaseUrl is required');
}

if (!workflowId) {
  throw new Error('workflowId is required');
}

if (!githubToken) {
  throw new Error('githubToken is required. Set GITHUB_TOKEN in n8n or hardcode the value in Build Poll Config.');
}

const reviewerLogins = new Set(
  parseJsonArray(config.reviewerLoginsJson, 'reviewerLoginsJson').map((entry) =>
    entry.toLowerCase(),
  ),
);
if (reviewerLogins.size === 0) {
  throw new Error('reviewerLoginsJson must contain at least one login');
}

const allowedProjectIds = new Set(
  parseJsonArray(config.allowedProjectIdsJson, 'allowedProjectIdsJson'),
);
const allowedRepos = new Set(
  parseJsonArray(config.allowedReposJson, 'allowedReposJson').map((entry) =>
    entry.toLowerCase(),
  ),
);
const ignoredRepos = new Set(
  parseJsonArray(config.ignoredReposJson, 'ignoredReposJson').map((entry) =>
    entry.toLowerCase(),
  ),
);

const bootstrapLookbackHours = parsePositiveInteger(
  config.bootstrapLookbackHours,
  'bootstrapLookbackHours',
  24,
);
const maxPullRequestsPerRepo = parsePositiveInteger(
  config.maxPullRequestsPerRepo,
  'maxPullRequestsPerRepo',
  25,
);
const rememberedCommentIds = parsePositiveInteger(
  config.rememberedCommentIds,
  'rememberedCommentIds',
  1000,
);
const githubApiBase = 'https://api.github.com';
const githubHeaders = {
  Accept: 'application/vnd.github+json',
  Authorization: `Bearer ${githubToken}`,
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-coderabbit-thread-polling',
};

const requestVk = async (path) => {
  const response = await $helpers.httpRequest({
    method: 'GET',
    url: `${vkBaseUrl}${path}`,
    json: true,
  });

  if (!response || response.success !== true) {
    throw new Error(
      `VK request failed for ${path}: ${response?.error || 'unknown error'}`,
    );
  }

  return response.data;
};

const normalizeGitHubError = (error) => ({
  status:
    error?.statusCode ||
    error?.response?.statusCode ||
    error?.response?.status ||
    null,
  message:
    error?.message ||
    error?.description ||
    error?.response?.body?.message ||
    'unknown GitHub error',
});

const requestGitHubPage = async (path, query = {}) => {
  return $helpers.httpRequest({
    method: 'GET',
    url: `${githubApiBase}${path}`,
    qs: query,
    headers: githubHeaders,
    json: true,
  });
};

const requestGitHubGraphQL = async (query, variables) => {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: `${githubApiBase}/graphql`,
    headers: {
      ...githubHeaders,
      'Content-Type': 'application/json',
    },
    body: {
      query,
      variables,
    },
    json: true,
  });

  if (Array.isArray(response?.errors) && response.errors.length > 0) {
    const message = response.errors
      .map((entry) => entry?.message || 'unknown GraphQL error')
      .join(', ');
    throw new Error(message);
  }

  return response?.data || null;
};

const listPaginatedGitHub = async ({ path, query = {}, stopWhen, mapItem }) => {
  const collected = [];
  let page = 1;

  while (true) {
    const pageItems = await requestGitHubPage(path, {
      ...query,
      per_page: 100,
      page,
    });

    if (!Array.isArray(pageItems) || pageItems.length === 0) {
      break;
    }

    for (const item of pageItems) {
      if (stopWhen && stopWhen(item, collected)) {
        return collected;
      }

      collected.push(mapItem ? mapItem(item) : item);
    }

    if (pageItems.length < 100) {
      break;
    }

    page += 1;
  }

  return collected;
};

const REVIEW_THREADS_QUERY = `
  query($owner: String!, $repo: String!, $pr: Int!, $after: String) {
    repository(owner: $owner, name: $repo) {
      pullRequest(number: $pr) {
        reviewThreads(first: 100, after: $after) {
          pageInfo {
            hasNextPage
            endCursor
          }
          nodes {
            id
            isResolved
            isOutdated
            path
            line
            comments(first: 100) {
              nodes {
                id
                body
                createdAt
                url
                path
                line
                originalLine
                diffHunk
                author {
                  login
                }
              }
            }
          }
        }
      }
    }
  }
`;

const listOpenReviewThreads = async (owner, repo, pullNumber) => {
  const threads = [];
  let after = null;

  while (true) {
    const data = await requestGitHubGraphQL(REVIEW_THREADS_QUERY, {
      owner,
      repo,
      pr: pullNumber,
      after,
    });

    const reviewThreads = data?.repository?.pullRequest?.reviewThreads;
    if (!reviewThreads) {
      return threads;
    }

    for (const thread of reviewThreads.nodes || []) {
      if (!thread || thread.isResolved) {
        continue;
      }

      threads.push({
        threadId: thread.id,
        isResolved: Boolean(thread.isResolved),
        isOutdated: Boolean(thread.isOutdated),
        path: thread.path || '',
        line: thread.line ?? null,
        comments: (thread.comments?.nodes || []).map((comment) => ({
          id: String(comment?.id || ''),
          authorLogin: String(comment?.author?.login || ''),
          body: String(comment?.body || ''),
          createdAt: String(comment?.createdAt || ''),
          url: String(comment?.url || ''),
          path: String(comment?.path || thread.path || ''),
          line: comment?.line ?? comment?.originalLine ?? thread.line ?? null,
          originalLine: comment?.originalLine ?? null,
          diffHunk: String(comment?.diffHunk || ''),
        })),
      });
    }

    if (!reviewThreads.pageInfo?.hasNextPage || !reviewThreads.pageInfo?.endCursor) {
      return threads;
    }

    after = reviewThreads.pageInfo.endCursor;
  }
};

const projects = await requestVk('/api/projects');
const selectedRepoMap = new Map();

for (const project of projects) {
  const projectId = String(project.id);

  if (allowedProjectIds.size > 0 && !allowedProjectIds.has(projectId)) {
    continue;
  }

  const workflowAssociation = await requestVk(
    `/api/projects/${projectId}/workflow-association`,
  );

  if (!workflowAssociation || workflowAssociation.workflow_id !== workflowId) {
    continue;
  }

  const githubRepositories = await requestVk(
    `/api/projects/${projectId}/github-repositories`,
  );

  for (const repository of githubRepositories) {
    const fullName = String(repository.github_full_name || '').toLowerCase();

    if (!fullName) {
      continue;
    }

    if (allowedRepos.size > 0 && !allowedRepos.has(fullName)) {
      continue;
    }

    if (ignoredRepos.has(fullName)) {
      continue;
    }

    const existing = selectedRepoMap.get(fullName);
    if (existing) {
      existing.projectIds.push(projectId);
      existing.projectNames.push(project.name);
      continue;
    }

    selectedRepoMap.set(fullName, {
      repoId: repository.repo_id,
      repoName: repository.repo_name,
      displayName: repository.display_name,
      path: repository.path,
      githubOwner: repository.github_owner,
      githubRepoName: repository.github_repo_name,
      githubFullName: repository.github_full_name,
      projectIds: [projectId],
      projectNames: [project.name],
    });
  }
}

const selectedRepos = Array.from(selectedRepoMap.values()).sort((left, right) =>
  left.githubFullName.localeCompare(right.githubFullName),
);

const staticData = $getWorkflowStaticData('global');
const state = staticData.coderabbitReviewExtraction || {};
const pollStartedAt = new Date().toISOString();
const bootstrapAnchor = new Date(
  Date.now() - bootstrapLookbackHours * 60 * 60 * 1000,
).toISOString();
const pollAfter = typeof state.lastPolledAt === 'string' ? state.lastPolledAt : bootstrapAnchor;
const pollAfterMs = Date.parse(pollAfter);
const knownCommentIds = new Set(
  Array.isArray(state.processedThreadCommentIds)
    ? state.processedThreadCommentIds.map((entry) => String(entry))
    : [],
);

const inaccessibleRepos = [];
const extractedPullRequests = [];
const newCommentIds = [];
let inspectedPullRequests = 0;
let inspectedThreads = 0;

for (const selectedRepo of selectedRepos) {
  const repoPath = `/repos/${selectedRepo.githubOwner}/${selectedRepo.githubRepoName}`;

  let pullRequests;
  try {
    pullRequests = await listPaginatedGitHub({
      path: `${repoPath}/pulls`,
      query: {
        state: 'open',
        sort: 'updated',
        direction: 'desc',
      },
      stopWhen: (pullRequest, collected) => {
        const updatedAt = Date.parse(String(pullRequest.updated_at || ''));
        if (Number.isFinite(updatedAt) && updatedAt < pollAfterMs) {
          return true;
        }

        return collected.length >= maxPullRequestsPerRepo;
      },
      mapItem: (pullRequest) => ({
        number: pullRequest.number,
        title: pullRequest.title,
        url: pullRequest.html_url,
        updatedAt: pullRequest.updated_at,
      }),
    });
  } catch (error) {
    const githubError = normalizeGitHubError(error);
    if (githubError.status === 403 || githubError.status === 404) {
      inaccessibleRepos.push({
        repo: selectedRepo.githubFullName,
        status: githubError.status,
        message: githubError.message,
      });
      continue;
    }

    throw new Error(
      `Failed to list pull requests for ${selectedRepo.githubFullName}: ${githubError.message}`,
    );
  }

  inspectedPullRequests += pullRequests.length;

  for (const pullRequest of pullRequests) {
    const threads = await listOpenReviewThreads(
      selectedRepo.githubOwner,
      selectedRepo.githubRepoName,
      pullRequest.number,
    );
    inspectedThreads += threads.length;

    const matchingThreads = [];

    for (const thread of threads) {
      const matchingCommentIds = [];
      const serializedComments = thread.comments.map((comment) => {
        const createdAtMs = Date.parse(comment.createdAt);
        const isNewCoderabbitComment =
          reviewerLogins.has(comment.authorLogin.toLowerCase()) &&
          Number.isFinite(createdAtMs) &&
          createdAtMs >= pollAfterMs &&
          !knownCommentIds.has(comment.id);

        if (isNewCoderabbitComment) {
          matchingCommentIds.push(comment.id);
        }

        return {
          id: comment.id,
          authorLogin: comment.authorLogin,
          body: comment.body,
          createdAt: comment.createdAt,
          url: comment.url,
          path: comment.path,
          line: comment.line,
          originalLine: comment.originalLine,
          diffHunk: comment.diffHunk,
          isNewCoderabbitComment,
        };
      });

      if (matchingCommentIds.length === 0) {
        continue;
      }

      matchingThreads.push({
        threadId: thread.threadId,
        path: thread.path,
        line: thread.line,
        isResolved: thread.isResolved,
        isOutdated: thread.isOutdated,
        matchingCommentCount: matchingCommentIds.length,
        comments: serializedComments,
      });

      for (const commentId of matchingCommentIds) {
        newCommentIds.push(commentId);
        knownCommentIds.add(commentId);
      }
    }

    if (matchingThreads.length === 0) {
      continue;
    }

    extractedPullRequests.push({
      repo: selectedRepo.githubFullName,
      owner: selectedRepo.githubOwner,
      repoName: selectedRepo.githubRepoName,
      pullNumber: pullRequest.number,
      pullRequestTitle: pullRequest.title,
      pullRequestUrl: pullRequest.url,
      selectedProjects: selectedRepo.projectNames,
      threadCount: matchingThreads.length,
      matchingCommentCount: matchingThreads.reduce(
        (total, thread) => total + thread.matchingCommentCount,
        0,
      ),
      threads: matchingThreads,
    });
  }
}

const nextProcessedThreadCommentIds = Array.from(
  new Set([
    ...newCommentIds,
    ...(Array.isArray(state.processedThreadCommentIds)
      ? state.processedThreadCommentIds.map((entry) => String(entry))
      : []),
  ]),
).slice(0, rememberedCommentIds);

staticData.coderabbitReviewExtraction = {
  workflowId,
  lastPolledAt: pollStartedAt,
  selectedReposByFullName: Object.fromEntries(
    selectedRepos.map((repo) => [repo.githubFullName.toLowerCase(), repo]),
  ),
  processedThreadCommentIds: nextProcessedThreadCommentIds,
};

return [
  {
    json: {
      status: extractedPullRequests.length > 0 ? 'captured' : 'no_matches',
      workflowId,
      pollStartedAt,
      previousPollCheckpoint: pollAfter,
      selectedRepoCount: selectedRepos.length,
      selectedRepos: selectedRepos.map((repo) => ({
        repo: repo.githubFullName,
        projects: repo.projectNames,
      })),
      inaccessibleRepos,
      inspectedPullRequestCount: inspectedPullRequests,
      inspectedThreadCount: inspectedThreads,
      pullRequestCount: extractedPullRequests.length,
      matchingCommentCount: extractedPullRequests.reduce(
        (total, pullRequest) => total + pullRequest.matchingCommentCount,
        0,
      ),
      pullRequests: extractedPullRequests,
    },
  },
];
